{
  "bioavailability_prediction": "low",
  "confidence": "moderate",
  "revision_action": "flip",
  "supportive_card_ids": ["C220", "C205", "C244", "C233"],
  "contradictory_card_ids": ["C08", "C10", "C07", "C03", "C06"],
  "prediction_basis_card_ids": ["C220", "C205", "C244", "C233"],
  "claims": [
    {
      "claim": "C220 explicitly identifies naloxone, the N-allyl-6-keto-14-hydroxy morphinan matching the query structure, as behaving like a high extraction ratio drug in clinical pharmacokinetic data, indicating extensive first-pass hepatic extraction and low oral systemic availability.",
      "card_ids": ["C220"]
    },
    {
      "claim": "C205 reports that the N-allyl morphinan levallorphan has a metabolic half-life of only 8.5 min in recombinant CYP3A4 (Clint 0.82 µL/min/pmol), providing close-scaffold evidence that N-allyl morphinans can undergo rapid oxidative metabolism.",
      "card_ids": ["C205"]
    },
    {
      "claim": "C244 reports morphine has low hepatic availability (0.13 ± 0.06) in isolated perfused rat liver with clearance approaching perfusate flow, and C233 shows naltrexone, the closest 6-keto-14-hydroxy analog, undergoes measurable human hepatic cytosolic metabolism to 6β-naltrexol; together these support high first-pass extraction in this morphinan series.",
      "card_ids": ["C244", "C233"]
    },
    {
      "claim": "Direct human F values for other morphinans (morphine 29.2 ± 7.2%, codeine 80.5%, ethylmorphine median 0.74) are above the 20% threshold, but these are N-methyl/N-ethyl analogs without the 6-keto-14-hydroxy/N-allyl combination and do not override the query-specific high-extraction evidence.",
      "card_ids": ["C08", "C10", "C07", "C03", "C06"]
    },
    {
      "claim": "L4/L5 absorption evidence (codeine human fraction absorbed >90%; naltrexone Caco-2 Papp A-B 15.1 ×10^-6 cm/s with efflux ratio 1.3) indicates absorption is not the limiting step, so the low prediction is driven by first-pass/clearance rather than poor permeability.",
      "card_ids": ["C151", "C174"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "high",
      "direction": "supportive",
      "decision_effect": "changed",
      "card_ids": ["C220", "C205", "C244", "C233"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query (naloxone) is supplied; C220 is a qualitative high-extraction classification rather than a numeric F.",
    "No human oral versus IV AUC comparison for naloxone is provided, so the quantitative hepatic extraction fraction for the query is not directly measured.",
    "C205 is for levallorphan, not the query, and C244 is rat isolated perfused liver; species and assay differences limit direct quantification.",
    "L1 direct F values are for other morphinans with different N-substituents and oxidation states; transfer to the N-allyl-6-keto-14-hydroxy morphinan is limited.",
    "No query-specific permeability or efflux data are supplied; absorption is inferred from naltrexone, morphine, and codeine."
  ],
  "decision_summary": "Flip to low: L6 provides query-specific mechanistic evidence that naloxone behaves like a high extraction ratio drug (C220), supported by rapid CYP3A4 metabolism of the N-allyl morphinan levallorphan (C205) and high first-pass extraction in the morphinan series (C244, C233). Absorption evidence indicates permeability is not limiting, so the low prediction is driven by first-pass hepatic clearance. Confidence is moderate because no numeric oral F for the query is supplied."
}

